// Package helpers holds the code the calc suite's step definitions share.
//
// The calculator is reached only as the declared CLI of
// docs/architecture/calc-cli.yaml: `go run ./services/calc halve [--exact] VALUE`
// and `go run ./services/calc double VALUE`, run as a process from the host root.
// Nothing here halves or doubles a number; the number travels to the command as
// the step captured it, and the command's stdout travels back untouched but for
// the single line terminator the CLI document says it ends with.
package helpers

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

// The words a step's captures use, and the CLI names they select.
const (
	// OperationHalves and OperationDoubles are the two alternatives the
	// operation capture can hold.
	OperationHalves  = "halves"
	OperationDoubles = "doubles"

	// CommandHalve and CommandDouble are the commands declared in the
	// calculator's CLI document.
	CommandHalve  = "halve"
	CommandDouble = "double"

	// ExactlyWord is the optional word the exact capture holds when the step
	// says it; ExactFlag is the flag halve declares for it.
	ExactlyWord = "exactly"
	ExactFlag   = "--exact"

	// ServicePackage is the package the declared commands are run from, as
	// named by the CLI document, relative to the host root.
	ServicePackage = "./services/calc"
)

// runTimeout bounds one calculator run so a wedged process reports itself
// instead of hanging the suite.
const runTimeout = 2 * time.Minute

// CommandForOperation turns the operation the step names into the command the
// CLI document declares for it.
func CommandForOperation(operation string) (string, error) {
	switch operation {
	case OperationHalves:
		return CommandHalve, nil
	case OperationDoubles:
		return CommandDouble, nil
	default:
		return "", fmt.Errorf(
			"operation %q names no declared command: the calculator CLI declares %q and %q only",
			operation, OperationHalves, OperationDoubles,
		)
	}
}

// CalculatorArgs builds the argument list for one run of the calculator: the
// command the operation names, --exact when the step said "exactly", and the
// step's number as the VALUE argument, passed on as captured.
func CalculatorArgs(operation, exact, number string) ([]string, error) {
	command, err := CommandForOperation(operation)
	if err != nil {
		return nil, err
	}

	argv := []string{command}

	switch exact {
	case "":
		// The step did not say "exactly", so no flag is passed.
	case ExactlyWord:
		if command != CommandHalve {
			return nil, fmt.Errorf(
				"the calculator CLI declares the %s flag on %q only, so %q cannot be run exactly",
				ExactFlag, CommandHalve, command,
			)
		}
		argv = append(argv, ExactFlag)
	default:
		return nil, fmt.Errorf(
			"exact capture %q is neither empty nor %q", exact, ExactlyWord,
		)
	}

	return append(argv, number), nil
}

// HostRoot is the directory the declared commands are run from: the nearest
// ancestor of the suite's working directory holding a go.mod, which is the host
// root the CLI document names `./services/calc` relative to.
func HostRoot() (string, error) {
	dir, err := os.Getwd()
	if err != nil {
		return "", fmt.Errorf("locating the host root: %w", err)
	}
	for {
		info, statErr := os.Stat(filepath.Join(dir, "go.mod"))
		if statErr == nil && !info.IsDir() {
			return dir, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", fmt.Errorf(
				"no go.mod above the suite's working directory, so the host root to run %s from is unknown",
				ServicePackage,
			)
		}
		dir = parent
	}
}

// TrimLine drops the single trailing line terminator the CLI document says each
// command's stdout ends with, and nothing else.
func TrimLine(out string) string {
	return strings.TrimSuffix(strings.TrimSuffix(out, "\n"), "\r")
}

// RunCalculator runs the calculator as a process from the host root with the
// given command arguments and returns its stdout. The inherited environment is
// left in place, so the Go build and temporary-directory settings of the run
// carry through.
func RunCalculator(argv ...string) (string, error) {
	root, err := HostRoot()
	if err != nil {
		return "", err
	}

	ctx, cancel := context.WithTimeout(context.Background(), runTimeout)
	defer cancel()

	full := append([]string{"run", ServicePackage}, argv...)
	cmd := exec.CommandContext(ctx, "go", full...)
	cmd.Dir = root

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	runErr := cmd.Run()
	output := TrimLine(stdout.String())
	if runErr == nil {
		return output, nil
	}

	printed := strings.TrimSpace(stderr.String())
	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
		return output, fmt.Errorf(
			"go %s in %s did not finish within %s; stderr: %s",
			strings.Join(full, " "), root, runTimeout, printed,
		)
	}
	return output, fmt.Errorf(
		"go %s in %s: %w; stderr: %s",
		strings.Join(full, " "), root, runErr, printed,
	)
}

// This file holds the output observation the calc suite's Then steps share.
//
// Nothing here produces or predicts what the calculator prints: the printed
// text arrives as the suite kept it, and the step's pattern arrives as the step
// wrote it. The only work done is compiling that pattern and reporting whether
// it has a match in the kept text.
package helpers

import (
	"fmt"
	"regexp"
)

// The words the comparison capture can hold, and what each one requires of the
// kept output.
const (
	// ComparisonMatches requires the step's pattern to have a match in the
	// kept stdout.
	ComparisonMatches = "matches"

	// ComparisonDoesNotMatch requires the step's pattern to have no match in
	// the kept stdout.
	ComparisonDoesNotMatch = "does not match"
)

// CompareOutput matches pattern, a Go regular expression taken verbatim from
// the step, against output, the stdout the suite kept without its trailing
// newline, and reports whether the comparison the step named holds.
//
// The pattern is unanchored on purpose: it is used exactly as the step wrote
// it, so a step that wants the whole line to be the value anchors it itself.
func CompareOutput(output, comparison, pattern string) error {
	expr, err := regexp.Compile(pattern)
	if err != nil {
		return fmt.Errorf(
			"the step's pattern %q is not a Go regular expression: %w",
			pattern, err,
		)
	}

	matched := expr.MatchString(output)

	switch comparison {
	case ComparisonMatches:
		if !matched {
			return fmt.Errorf(
				"the calculator printed %q, which has no match for %q",
				output, pattern,
			)
		}
		return nil
	case ComparisonDoesNotMatch:
		if matched {
			return fmt.Errorf(
				"the calculator printed %q, which has a match for %q",
				output, pattern,
			)
		}
		return nil
	default:
		return fmt.Errorf(
			"comparison capture %q is neither %q nor %q",
			comparison, ComparisonMatches, ComparisonDoesNotMatch,
		)
	}
}

package steps

import (
	"fmt"

	"fixture/conceptbodiescases/tests/calc/helpers"
)

//truebdd:concept when "operation"
func concept7b86a45f32a2af1379e8139ecafca2e1995ea6f5ea105d09465e201fb17f9fd4(state *State, args []string) error {
	if len(args) != 3 {
		return fmt.Errorf("want 3 captures (exact, operation, number), got %d: %q", len(args), args)
	}
	exact, operation, number := args[0], args[1], args[2]

	argv, err := helpers.CalculatorArgs(operation, exact, number)
	if err != nil {
		return err
	}

	output, err := helpers.RunCalculator(argv...)
	if err != nil {
		return err
	}

	state.Output = output
	return nil
}

package steps

import (
	"fmt"

	"fixture/conceptbodiescases/tests/calc/helpers"
)

//truebdd:concept then "output"
func concept95123e5878d35715c67b1f901cd0d6e1fcafc896021616abdece460efff6ed7e(state *State, args []string) error {
	if len(args) != 2 {
		return fmt.Errorf("want 2 captures (comparison, pattern), got %d: %q", len(args), args)
	}
	comparison, pattern := args[0], args[1]

	// state.Output is the stdout the operation step kept, already without the
	// single trailing line terminator the CLI document declares. The CLI prints
	// a value on every successful run, so an empty kept output means no run was
	// observed rather than an empty answer, and the step says so instead of
	// silently passing a "does not match".
	if state.Output == "" {
		return fmt.Errorf(
			"no calculator output was kept, so it cannot be observed to %s %q: the operation step must run first",
			comparison, pattern,
		)
	}

	return helpers.CompareOutput(state.Output, comparison, pattern)
}

package steps

func Register(suite Registrar) {

	suite.Step("^the Owner(?: (exactly))? (halves|doubles) (-?\\d+)$", concept7b86a45f32a2af1379e8139ecafca2e1995ea6f5ea105d09465e201fb17f9fd4)

	suite.Step("^the calculator's output (matches|does not match) (.+)$", concept95123e5878d35715c67b1f901cd0d6e1fcafc896021616abdece460efff6ed7e)
}
